// Cross-world validation (directive §14). Each world in data/forge-samples/*.spec.json was
// generated by the real local model from a one-paragraph description (see
// scripts/forge-suite.sh; drafts and reports are kept next to the specs). This test plays
// every recorded world through the same universal checklist with the real engine.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { Game } from '../src/engine/game.js';
import { attach } from '../src/engine/sim.js';
import { executeTurn } from '../src/engine/turn.js';
import { normalizeInterpretation, blankAction } from '../src/ai/schema.js';
import { fallbackInterpret } from '../src/ai/fallback-parser.js';
import { reconcile } from '../src/engine/ledger.js';
import { conservationCheck } from '../src/engine/inventory.js';
import { activeRules } from '../src/engine/worldrules.js';
import { retrieveMemories } from '../src/engine/memory.js';

const DIR = 'data/forge-samples';
const specs = fs.existsSync(DIR) ? fs.readdirSync(DIR).filter((f) => f.endsWith('.spec.json')) : [];

function act(game, ...actions) {
  const interp = normalizeInterpretation({ mode: 'act', intent: 't', actions: actions.map((a) => ({ ...blankAction(a.type), ...a })), plan_title: null, risks: [], question: null, reason: null });
  assert.ok(interp.ok, interp.errors?.join(';'));
  return executeTurn(game, { input: JSON.stringify(actions), interp: interp.value, source: 'test' });
}
function say(game, text) {
  const n = normalizeInterpretation(fallbackInterpret(text));
  if (!n.ok || !['act', 'plan'].includes(n.value.mode)) return null;
  return executeTurn(game, { input: text, interp: n.value, source: 'fallback' });
}

test('recorded AI-forged worlds exist for cross-world validation', { skip: specs.length ? false : 'no recorded worlds yet' }, () => {
  assert.ok(specs.length >= 1);
});

for (const f of specs) {
  test(`cross-world: ${f.replace('.spec.json', '')}`, () => {
    const spec = JSON.parse(fs.readFileSync(path.join(DIR, f), 'utf8'));
    const file = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'saturn-xw-')), 'w.saturn');
    const g = attach(Game.create(file, { def: spec, seed: 11, player: { name: 'Tester', background: spec.backgrounds[0].id } }));
    // the world's own rules are in force
    assert.deepEqual(g.rules.skillIds.sort(), spec.skills.map((s) => s.id).sort(), 'world-specific skills');
    assert.equal(g.rules.currency.name, spec.currency.name);
    const start = g.player().location_id;
    assert.equal(start, spec.start.location);
    // look, talk, ask about something they know
    assert.equal(act(g, { type: 'look' }).outcomes[0].status, 'done');
    const npcHere = g.charactersAt(start).find((c) => c.kind === 'npc') || null;
    const someone = npcHere || g.char(spec.npcs[0].id);
    if (!npcHere) act(g, { type: 'move', destination: g.location(someone.location_id).name });
    const talked = act(g, { type: 'talk', target: someone.name, approach: 'ask', topic: spec.facts[0]?.subject || 'news' });
    assert.equal(talked.outcomes[0].status, 'done', talked.outcomes[0].error?.message);
    // memory: the NPC remembers the player
    const mem = retrieveMemories(g.db, { ownerId: someone.id, now: g.time, participants: ['player'], text: 'talked' });
    assert.ok(mem.memories.some((m) => /Tester/.test(m.summary)), 'NPC remembers the conversation');
    // economy: find something to buy that the player can afford, priced in the world currency
    const merchants = spec.npcs.filter((n) => n.shop?.sells?.length);
    assert.ok(merchants.length >= 2, 'world has merchants');
    const m = merchants.find((x) => x.shop.sells.some((t) => spec.item_types.find((i) => i.id === t)?.base_value <= g.balance('player'))) || merchants[0];
    if (g.player().location_id !== g.char(m.id).location_id) act(g, { type: 'move', destination: g.location(g.char(m.id).location_id).name });
    const cheap = m.shop.sells.map((t) => spec.item_types.find((i) => i.id === t)).filter(Boolean).sort((a, b) => a.base_value - b.base_value)[0];
    const money0 = g.balance('player');
    const b = act(g, { type: 'buy', target: g.char(m.id).name, item: cheap.name, quantity: 1 });
    if (b.outcomes[0].status === 'done') assert.ok(g.balance('player') < money0, 'paid in world currency');
    else assert.ok(['insufficient_funds', 'out_of_stock', 'not_here'].includes(b.outcomes[0].error.code), b.outcomes[0].error.message);
    // skill checks with world skills: train a drillable skill, study with a teacher if any
    const drill = spec.skills.find((s) => !s.trained);
    const tr = act(g, { type: 'train', skill: drill.label, hours: 3 });
    assert.notEqual(tr.outcomes[0].status, 'blocked', tr.outcomes[0].error?.message);
    // free text through the deterministic parser, world-agnostic phrasing
    assert.ok(say(g, 'investigate'), 'parser handles generic phrasing');
    // world rules: installed and resolvable through a real check when usable
    const rules = activeRules(g);
    assert.ok(rules.length >= 1, 'world-specific rules installed');
    const open = rules.find((r) => !r.spec.requires?.capability && !(r.spec.costs?.items || []).length && !(r.spec.requires?.tools || []).length && !r.spec.requires?.target && !r.spec.effects.success.some((e) => e.type === 'travel'));
    if (open) {
      const u = act(g, { type: 'use_ability', target: open.name });
      assert.ok(u.outcomes[0].status !== 'blocked' || ['underqualified', 'wrong_place', 'exhausted'].includes(u.outcomes[0].error.code), u.outcomes[0].error?.message);
    } else {
      const learnable = rules.find((r) => r.spec.requires?.capability);
      if (learnable) assert.equal(act(g, { type: 'use_ability', target: learnable.name }).outcomes[0].error.code, 'not_learned');
    }
    // time: two weeks of world simulation; NPCs act; integrity holds
    for (let i = 0; i < 14; i++) act(g, { type: 'wait', hours: 24 });
    assert.ok(g.db.prepare('SELECT COUNT(*) n FROM npc_decisions').get().n > 0, 'NPCs make autonomous decisions');
    assert.deepEqual(reconcile(g.db), []);
    assert.deepEqual(conservationCheck(g.db), []);
    // save and reload
    const fp = JSON.stringify({ t: g.time, m: g.balance('player'), r: activeRules(g).map((r) => r.id), held: g.held('player').map((i) => [i.type_id, i.quantity]) });
    g.close();
    const g2 = attach(Game.open(file));
    assert.equal(JSON.stringify({ t: g2.time, m: g2.balance('player'), r: activeRules(g2).map((r) => r.id), held: g2.held('player').map((i) => [i.type_id, i.quantity]) }), fp);
    g2.close();
  });
}
